import json, os, numpy as np
import lib
O = lib.OUT
def L(p): return json.load(open(O + "/" + p)) if os.path.exists(O + "/" + p) else None
N, N2, Fd, SA = L("noise_results.json"), L("noise_results2.json"), L("fade_results.json"), L("scale_ai_results.json")
f = lambda s: f"{s['n']:.0f} | {s['win']:.1f} | {s['pf']:.2f} | {s['avg']:+.1f} | {s['net']:,.0f} | {s['dd']:,.0f}"
ev = lambda b: f"{b['pass_']:.0f} / {b['bust']:.0f}"
def verdict_noise(r, b):
    isb, jb = b["IS"], b["J"]; i, j = r["IS"], r["J"]
    j_better = j["pf"] > jb["pf"] and j["avg"] >= jb["avg"] and r["boot25_J"]["pass_"] >= b["boot25_J"]["pass_"] and r["boot25_J"]["bust"] <= b["boot25_J"]["bust"]
    i_ok = i["pf"] >= isb["pf"] - 0.03 and i["avg"] >= isb["avg"] - 0.5 and i["net"] >= 0.85 * isb["net"] and r["boot25_IS"]["pass_"] >= b["boot25_IS"]["pass_"] - 1 and r["boot25_IS"]["bust"] <= b["boot25_IS"]["bust"] + 1
    prof = j["net"] >= jb["net"] * 0.97
    return "ADOPT" if (j_better and i_ok and prof) else ("reject")
out = []
w = out.append
w("# Session 19 - Refine all strategies (research only; nothing in the app, config or tests changed)\n")
w("Generated by `build_report.py` from the JSON files in this folder. Scripts: `lib.py` (data, stats, Pro eval simulator), `noise2.py` (NOISE generator = session-17 preset C + entry hook), `run_noise.py`, `run_noise2.py`, `fade2.py`, `run_fade.py`, `run_scale_ai.py`, `of_long.py`, `ar_long.py`.\n")
w("## 0. Protocol (read first)\n")
w("- **Data (cached only, Databento locked):** MNQ.v.0 1m 2019-05-06..2026-11-05 (1,867 RTH days) and MGC 1m 2019..2026 (`split_raw/MGC_<year>.csv`). **No MES cache exists anywhere** (searched repo + scratchpad), so MES was not tested.")
w("- **Pick = IS 2019-05-06..2025-11-05 (6.5 years). Judge = J, the last 12 months 2025-11-06..2026-11-06.** Every threshold (percentiles etc.) is computed on IS only. HO24 (2024-01..2026-11) is shown only as a secondary check: it overlaps IS, and it and J were already seen in sessions 9-18, so J is *not* a virgin sample.")
w("- **Costs:** 1 micro, $1.00 RT (MGC $1.60) + 1 tick on every entry, stop and flat exit, stop-first inside a 1m bar; same as sessions 9-18. NOISE baseline = session-17 **preset C** ($250 stop, +100 pt lock -> entry +10, hourly checks 10:00-15:00, max 3/day). It reproduces the committed numbers exactly (HO24: 427 trades, 52.2 %, +$27.19, PF 1.43, max DD $2,028; J full year = 149 trades, 55 %, PF 1.53, +$39.3, net $5,857).")
w("- **Eval sim (Lucid Pro, EOD trailing MLL, lock at +MLL+100, target per size 1,250/3,000/6,000/9,000, soft DLL 1,200/1,800/2,700 on 50/100/150K, none on 25K eval; pass-in-one-day allowed, no consistency):** block bootstrap (10-day blocks, 600 paths, 400 sessions) of the era's real days. `PASS / BUST` are bootstrap %. Pro 25K = 1 micro, Pro 50K = 2 micros (app default size table). Streams are scaled linearly by contracts (costs scale too).")
w("- **J is small.** 149 NOISE trades in 12 months; a random-direction version of NOISE (same timing, exits, lock) scores J PF 1.13, +$11.5/trade on average, and its J bootstrap pass ranges from 19 % to 64 % across seeds (median about 50 %). So a +/-5 pt PASS difference on J is inside the noise; I therefore also require IS agreement.")
w("- **Decision rule (written before looking at J):** ADOPT only if J is better (PF up, $/trade >= base, boot pass >= base and bust <= base, net >= 97 % of base) AND IS is not worse by much (PF >= base-0.03, $/trade >= base-0.5, net >= 85 % of base, boot pass/bust within 1 pt). Otherwise reject. The CLAUDE.md win-rate/profit rule (never lower measured win rate or profit) is applied through the net-profit test.\n")

# ---------------- NOISE
w("## 1. NOISE (MNQ, main strategy) - baseline preset C vs refinements\n")
w("Columns: trades | win % | PF | $/trade | net $ | max DD $ for IS and J, then Pro 25K (1 micro) and Pro 50K (2 micros) bootstrap PASS / BUST %. `dNet J` = paired block-bootstrap 95 % interval of (net - base net) over J days.\n")
w("| Variant | IS n | win | PF | $/tr | net | maxDD | J n | win | PF | $/tr | net | maxDD | 25K J pass/bust | 25K IS pass/bust | 50K J pass/bust | 50K IS pass/bust | dNet J [95% CI] | Verdict |")
w("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
b = N["rows"][0]
rows = N["rows"] + (N2["combo"] if N2 else [])
for r in rows:
    v = "baseline" if r is b else verdict_noise(r, b)
    w(f"| {r['name']} | {f(r['IS'])} | {f(r['J'])} | {ev(r['boot25_J'])} | {ev(r['boot25_IS'])} | {ev(r['boot50_J'])} | {ev(r['boot50_IS'])} | {r['dJ'][0]:+,.0f} [{r['dJ'][1]:+,.0f}, {r['dJ'][2]:+,.0f}] | **{v}** |")
rd = N["rand"]
w(f"| random direction, same timing/exits/lock (30 seeds, mean) | {rd['IS']['n']:.0f} | {rd['IS']['win']:.1f} | {rd['IS']['pf']:.2f} | {rd['IS']['avg']:+.1f} | {rd['IS']['net']:,.0f} | {rd['IS']['dd']:,.0f} | {rd['J']['n']:.0f} | {rd['J']['win']:.1f} | {rd['J']['pf']:.2f} | {rd['J']['avg']:+.1f} | {rd['J']['net']:,.0f} | {rd['J']['dd']:,.0f} | seed0 {ev(rd['boot25_J'])} | | | | | benchmark |")
w("\nIS-only thresholds used: " + ", ".join(f"{k}={v:.4f}" for k, v in N["TH"].items()) + ".  Refinement R2 uses relative volume = cumulative volume to the check bar / mean cumulative volume at the same minute over the previous 14 days. R4 = (high-low so far today)/mean 14-day daily range. VA = prior-day RTH value area (70 %, from 1m closes). 'No new trades in the last 10 min' does not apply: NOISE only enters on the hourly checks (last 15:00); session 17 already tested an extra 15:30 check (worse).\n")
if N2:
    w("### Skip-Monday robustness (per calendar year, preset C, all trades)\n")
    w("| year | base n | base PF | base net | skip-Mon n | skip-Mon PF | skip-Mon net | Monday-only n | Monday PF | Monday net |")
    w("|---|---|---|---|---|---|---|---|---|---|")
    for y in N2["years"]: w(f"| {y['y']} | {y['base_n']} | {y['base_pf']:.2f} | {y['base_net']:,.0f} | {y['skip_n']} | {y['skip_pf']:.2f} | {y['skip_net']:,.0f} | {y['mon_n']} | {y['mon_pf']:.2f} | {y['mon_net']:,.0f} |")
    w("\nMondays lose or break even in 5 of 8 years (PF < 1 in 2019, 2020, 2023, 2024, 2026), but were strongly positive in 2021, 2022 and 2025, and skipping them lowers net profit in 3 years (2021, 2022, 2025). There is no market mechanism for a weekday effect here, so this is a data-mined filter whose benefit is concentrated in 2024 (Monday PF 0.46).\n")
# ---------------- Fade
w("## 2. Afternoon fade (PM_FADE, MNQ) - baseline vs refinements\n")
w("Rules as in `engine/pm_fade.py` / D58: on days NOISE preset C has not traded, close beyond VWAP +/- band*sd (sd = std of close-VWAP so far) from 13:01 to 15:29 -> fade at the next open + 1 tick, target = VWAP, stop $250 (124 pt), flat 15:55, one try per day. Left half = the fade stream alone (1 micro); right half = **NOISE + fade combined** vs NOISE alone (NOISE-only boot: 25K J "
  f"{ev(Fd['rows'][0]['noiseonly_boot25_J'])}, IS {ev(Fd['rows'][0]['noiseonly_boot25_IS'])}; 50K J {ev(Fd['rows'][0]['noiseonly_boot50_J'])}, IS {ev(Fd['rows'][0]['noiseonly_boot50_IS'])}).\n")
w("| Variant | IS n | win | PF | $/tr | net | maxDD | J n | win | PF | $/tr | net | maxDD | comb 25K J | comb 25K IS | comb 50K J | comb 50K IS | Verdict |")
w("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
fb = Fd["rows"][0]
def vf(r):
    j, i = r["J"], r["IS"]
    jb = j["pf"] > fb["J"]["pf"] and j["net"] >= 0.97 * fb["J"]["net"] and r["boot25_J"]["pass_"] >= fb["boot25_J"]["pass_"] and r["boot25_J"]["bust"] <= fb["boot25_J"]["bust"]
    io = i["pf"] >= fb["IS"]["pf"] - 0.03 and i["net"] >= .85 * fb["IS"]["net"] and r["boot25_IS"]["pass_"] >= fb["boot25_IS"]["pass_"] - 1
    return "ADOPT" if jb and io else "reject"
for r in Fd["rows"]:
    w(f"| {r['name']} | {f(r['IS'])} | {f(r['J'])} | {ev(r['boot25_J'])} | {ev(r['boot25_IS'])} | {ev(r['boot50_J'])} | {ev(r['boot50_IS'])} | **{'baseline' if r is fb else vf(r)}** |")
rf = Fd["rand"]
w(f"| random side, same timing (20 seeds, mean) | {rf['IS']['n']:.0f} | {rf['IS']['win']:.1f} | {rf['IS']['pf']:.2f} | {rf['IS']['avg']:+.1f} | | | {rf['J']['n']:.0f} | {rf['J']['win']:.1f} | {rf['J']['pf']:.2f} | {rf['J']['avg']:+.1f} | | | | | | | benchmark |")
w("\nIS-only thresholds: " + ", ".join(f"{k}={v:.3f}" for k, v in Fd["TH"].items()) + ". F5 is identical to baseline (a signal at 2 sd is always more than 3 pt from VWAP). F8 mirrors 'no new trades in the last 30 min'.\n")
# ---------------- AI / scale
if SA:
    w("## 3. AI Duo and NOISE + AI 50/50 split (cannot be backtested - simulated accuracy bands only)\n")
    w("AI Duo needs live LLM calls, so only the *value of a daily direction call* was simulated: day bias = true sign(close-open) with probability a (else wrong), and a NOISE trade against the bias is skipped (hard filter), 20 seeds, mean (PF median). The session-17 split study (NOISE half size + AI half size, `docs/results/session17/split_combo/RESULTS.md`) used the same idea with a full Duo; its conclusions stand and were not re-run: **split beats NOISE alone only if AI accuracy >= 60 % (Pro 50K/100K) or ~70 % (25K/150K); at realistic 50-56 % it does not; at 25K it puts 2 micros on a $1,000 loss limit and is not recommended.**\n")
    w("| AI accuracy | IS n | IS win | IS PF | IS $/tr | IS net | J n | J win | J PF | J $/tr | J net | 25K pass / bust IS | 25K pass / bust J |")
    w("|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    w(f"| none (NOISE baseline) | {f(b['IS']).split(' | ')[0]} | {b['IS']['win']:.1f} | {b['IS']['pf']:.2f} | {b['IS']['avg']:+.1f} | {b['IS']['net']:,.0f} | {b['J']['n']} | {b['J']['win']:.1f} | {b['J']['pf']:.2f} | {b['J']['avg']:+.1f} | {b['J']['net']:,.0f} | {ev(b['boot25_IS'])} | {ev(b['boot25_J'])} |")
    for r in SA["ai"]:
        w(f"| {100*r['acc']:.0f} % | {r['IS']['n']:.0f} | {r['IS']['win']:.1f} | {r['IS']['pf']:.2f} | {r['IS']['avg']:+.1f} | {r['IS']['net']:,.0f} | {r['J']['n']:.0f} | {r['J']['win']:.1f} | {r['J']['pf']:.2f} | {r['J']['avg']:+.1f} | {r['J']['net']:,.0f} | {r['IS']['pass']:.0f} / {r['IS']['bust']:.0f} | {r['J']['pass']:.0f} / {r['J']['bust']:.0f} |")
    w("\nBreak-even for the hard filter on **net profit** is about 70 % accuracy in IS and J (a 50-55 % call halves the trades and loses most of the profit). Win rate and PF rise with accuracy, but profit falls below baseline until ~70-75 %. Verdict: **keep the AI advisory (no hard block) until the ledger proves >= 70 %**, as D55 already says. No change.\n")
    w("## 4. Account-size scaling sanity (NOISE preset C, bootstrap bust %, contracts x pnl, each plan's MLL/DLL)\n")
    w("Rows = account size; columns = micros traded. Cell = PASS % / BUST % (400 sessions cap, 400 paths). Eras: **ALL** = 2019-05..2026-11 (7.5 years), IS, J. Bold = app default size table (25K:1, 50K:2, 100K:2, 150K:3); the user's plan 25K:1, 50K:2, 100K:3-4, 150K:5 is the 1/2/3/4/5 cells on the diagonal.\n")
    for strat in ("NOISE preset C", "NOISE preset C + skip Monday"):
        w(f"### {strat}\n")
        for e in ("ALL", "IS", "J"):
            w(f"**{e}**\n"); w("| size | 1 micro | 2 | 3 | 4 | 5 | worst day (1 micro) | DLL days hit at plan size |"); w("|---|---|---|---|---|---|---|---|")
            for size in (25, 50, 100, 150):
                rr = [r for r in SA["scale"] if r["strategy"] == strat and r["size"] == size]
                cells = []
                dflt = {25: 1, 50: 2, 100: 2, 150: 3}[size]
                for r in rr:
                    c = ev(r[e]); cells.append(f"**{c}**" if r["n"] == dflt else c)
                planN = {25: 1, 50: 2, 100: 3, 150: 5}[size]
                p = [r for r in rr if r["n"] == planN][0]
                w(f"| {size}K | " + " | ".join(cells) + f" | {rr[0]['worst_day']:,.0f} | {p['days_dll_hit']} |")
            w("")
# ---------------- OF
w("## 5. Order Flow types on ESTIMATED bars, 7.5 years (MNQ + MGC)\n")
w("**Everything here uses estimated signed volume (close-location x volume); there is no real delta, footprint, imbalance, DOM or gamma. Treat as a test of the *rules' skeleton*, not of real order flow.** 1 micro, 2R or trail exits, flat 16:00, max 2 trades/day, day ends after a win (teacher rule). Pick = IS (6.5 yr), J = last 12 months. `rand` = random side at the same moments with the same stop distance and mirrored target (6 seeds).\n")
for sym in ("MNQ", "MGC"):
    R = L(f"of_long_{sym}.json")
    if not R: continue
    w(f"### {sym}: AMT+ (context lock) and ATR-zone reversion\n")
    w("| Family | Params | IS n | win | PF | $/tr | net | maxDD | J n | win | PF | $/tr | net | maxDD | J 25K boot pass/bust | rand IS PF, $/tr | rand J PF, $/tr |")
    w("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    for r in R:
        bj = ev(r["boot_J"]) if "boot_J" in r else "-"
        w(f"| {r['fam']} | {json.dumps(r['kw']).replace('\"','')} | {f(r['IS'])} | {f(r['J'])} | {bj} | {r['rand']['IS']['pf']:.2f}, {r['rand']['IS']['avg']:+.1f} | {r['rand']['J']['pf']:.2f}, {r['rand']['J']['avg']:+.1f} |")
    w("")
w("AMT+ params: `k` = heavy-delta multiple of the 20-bar average |5m delta|; `lock` = context lock (open-30-min acceptance vs prior value area: accepted above -> longs only, below -> shorts only, inside -> only edge trades at VAL/VAH); `rvmin` = relative volume floor; `dead` = skip 11:15-13:30. ATR-zone params: `m` = volume-event multiple (5m bar volume >= m x avg20), `kk` = entry ATR(5m, Wilder 14) multiples beyond the zone edge, `stopmode` a = stop at (kk+1) ATR (rules file), b = 2R-floor stop (kk/2 ATR so the zone-edge target is >= 2R).\n")
AM = {s: L(f"ar_long_{s}.json") for s in ("MNQ", "MGC")}
if all(AM.values()):
    w("### AR Model (full four-layer bar approximation, `ar_long.py` = session-18 `ar.py` with the picking window extended to 2019-05..2025-11-05)\n")
    w("Layers: E = environment (compression skip), L = location, P = path, C = confirmation. PICK = IS, JUDGE = J (same bootstrap eval).\n")
    w("| Market | Session | best params (IS PF) | layers | IS n | win | PF | $/tr | net | J n | win | PF | $/tr | net |")
    w("|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    for s in ("MNQ", "MGC"):
        for sess in ("AM", "RTH"):
            if sess not in AM[s][s]: continue
            x = AM[s][s][sess]; bst = x["best"]
            for a in x["ablation"]:
                if a["layers"] in ("ELPC", "LC", "ELC", "EL", "L", "E" ) and a["pick"].get("n", 0):
                    p, j = a["pick"], a["judge"]
                    jj = f"{j.get('n',0)} | {j.get('win',0)} | {j.get('pf',0)} | {j.get('avg',0)} | {j.get('net',0)}"
                    w(f"| {s} | {sess} | k={bst['k']} {bst['mode']} | {a['layers']} | {p['n']} | {p['win']} | {p['pf']} | {p['avg']} | {p['net']} | {jj} |")
            w(f"| {s} | {sess} | random side, full model (8 seeds) | ELPC | | | PF {x['rand_pick']['pf']} | {x['rand_pick']['avg']} | | | | PF {x['rand_judge']['pf']} | {x['rand_judge']['avg']} | |")
